namespace CheckoutPricing.Domain;

public sealed class LoyaltyDiscountPolicy
{
    private const decimal DiscountCeilingRate = 10m;

    public decimal PayableTotalFor(string tier, decimal subtotal)
    {
        var baseRate = BaseRateFor(tier);
        var bonus = OrderSizeBonusFor(subtotal);
        var effectiveRate = Math.Min(baseRate + bonus, DiscountCeilingRate);

        var discount = decimal.Floor(subtotal * effectiveRate) / 100m;

        return subtotal - discount;
    }

    private static decimal BaseRateFor(string tier) => tier switch
    {
        "Bronze" => 5m,
        "Silver" => 7m,
        "Gold" => 9m,
        _ => throw new ArgumentOutOfRangeException(nameof(tier), tier, "Unknown loyalty tier."),
    };

    private static decimal OrderSizeBonusFor(decimal subtotal) => subtotal switch
    {
        >= 200.00m => 3m,
        >= 50.00m => 1m,
        _ => 0m,
    };
}
EOF
